use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::ops::Range;
use std::path::{Path, PathBuf};
use std::process::Command;

use anyhow::{Context, Result, ensure};
use pulldown_cmark::{CodeBlockKind, Event, Parser, Tag, TagEnd};
use serde::{Deserialize, Serialize};

use crate::markdown::{LocalDocument, markdown_options, sha256_hex};

pub(crate) const PROPERTY: &str = "confluence-cli.render-mermaid";
pub(crate) const SOURCE_TITLE: &str = "Mermaid source (confluence-cli)";
const PREFIX: &str = "confluence-cli-mermaid-";
const PROVENANCE_PREFIX: &str =
    "Generated by confluence-cli from Mermaid (source SHA-256, PNG SHA-256): ";

pub(crate) struct Diagram {
    pub range: Range<usize>,
    pub filename: String,
    pub source: String,
    pub top_level: bool,
}

pub(crate) fn enabled(doc: &LocalDocument) -> bool {
    enabled_in_properties(&doc.frontmatter.properties)
}

pub(crate) fn enabled_in_properties(properties: &BTreeMap<String, serde_json::Value>) -> bool {
    properties
        .get(PROPERTY)
        .and_then(serde_json::Value::as_bool)
        == Some(true)
}

pub(crate) fn generated_name(name: &str) -> bool {
    name.strip_prefix(PREFIX)
        .and_then(|name| name.strip_suffix(".png"))
        .is_some_and(|index| {
            !index.starts_with('0')
                && !index.is_empty()
                && index.bytes().all(|byte| byte.is_ascii_digit())
        })
}

pub(crate) fn fences(markdown: &str) -> Vec<Diagram> {
    let mut diagrams = Vec::new();
    let mut active = None;
    let mut depth = 0;
    for (event, range) in Parser::new_ext(markdown, markdown_options()).into_offset_iter() {
        match event {
            Event::Start(tag) => {
                if matches!(tag, Tag::CodeBlock(CodeBlockKind::Fenced(info)) if info.trim() == "mermaid")
                {
                    active = Some((range, String::new(), depth == 0));
                }
                depth += 1;
            }
            Event::Text(text) => {
                if let Some((_, source, _)) = &mut active {
                    source.push_str(&text);
                }
            }
            Event::End(tag) => {
                depth -= 1;
                if tag == TagEnd::CodeBlock
                    && let Some((range, source, top_level)) = active.take()
                {
                    diagrams.push(Diagram {
                        range,
                        filename: String::new(),
                        source,
                        top_level,
                    });
                }
            }
            _ => {}
        }
    }
    diagrams
}

impl Diagram {
    pub(crate) fn title(&self) -> Option<&str> {
        self.source
            .lines()
            .find_map(|line| line.trim().strip_prefix("accTitle:"))
            .map(str::trim)
            .filter(|title| !title.is_empty())
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub(crate) struct PendingPublish {
    pub body: String,
    pub names: Vec<Option<String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub upload: Option<PendingUpload>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub(crate) struct PendingUpload {
    pub name: String,
    pub source_hash: String,
    pub image_hash: String,
}

fn previous_diagrams(doc: &LocalDocument) -> Vec<Diagram> {
    let (body, names) = if let Some(pending) = &doc.sidecar.mermaid_pending {
        (&pending.body, &pending.names)
    } else if let Some(body) = &doc.sidecar.last_pulled_body_markdown {
        (body, &doc.sidecar.mermaid_attachments)
    } else {
        return Vec::new();
    };
    let diagrams = fences(body);
    if diagrams.len() != names.len() {
        return Vec::new();
    }
    diagrams
        .into_iter()
        .zip(names)
        .filter_map(|(mut diagram, name)| {
            diagram.filename.clone_from(name.as_ref()?);
            Some(diagram)
        })
        .collect()
}

pub(crate) fn name_diagrams(doc: &LocalDocument, diagrams: &mut [Diagram]) {
    let mut previous = previous_diagrams(doc);
    let attachments = doc.directory.join("attachments");
    let occupied = |name: &str| attachments.join(name).exists();
    let mut reserved: BTreeSet<_> = doc.sidecar.attachment_map.keys().cloned().collect();
    let mut seen = BTreeSet::new();
    previous.retain(|diagram| {
        generated_name(&diagram.filename)
            && !occupied(&diagram.filename)
            && seen.insert(diagram.filename.clone())
    });
    reserved.extend(seen);
    reserved.extend(doc.sidecar.mermaid_attachments.iter().flatten().cloned());

    match_diagrams(
        diagrams,
        &mut previous,
        |diagram| Some(&diagram.source),
        false,
    );
    match_diagrams(diagrams, &mut previous, Diagram::title, true);

    // With the same number of unmatched fences, preserve names for edits in
    // place. With insertions or deletions, only reuse identifiable diagrams.
    let unnamed = |diagram: &&Diagram| diagram.filename.is_empty();
    if diagrams.iter().filter(unnamed).count() == previous.len() {
        for (diagram, previous) in diagrams
            .iter_mut()
            .filter(|diagram| diagram.filename.is_empty())
            .zip(previous)
        {
            diagram.filename = previous.filename;
        }
    }

    let mut next_number = 1;
    for diagram in diagrams
        .iter_mut()
        .filter(|diagram| diagram.filename.is_empty())
    {
        loop {
            let name = format!("{PREFIX}{next_number}.png");
            next_number += 1;
            if !reserved.contains(&name) && !occupied(&name) {
                diagram.filename = name;
                break;
            }
        }
    }
}

fn match_diagrams(
    diagrams: &mut [Diagram],
    previous: &mut Vec<Diagram>,
    key: impl Fn(&Diagram) -> Option<&str>,
    unique: bool,
) {
    for index in 0..diagrams.len() {
        let diagram = &diagrams[index];
        if !diagram.filename.is_empty() {
            continue;
        }
        let Some(value) = key(diagram) else {
            continue;
        };
        let mut candidates = previous
            .iter()
            .enumerate()
            .filter(|(_, diagram)| key(diagram) == Some(value));
        let Some((candidate, _)) = candidates.next() else {
            continue;
        };
        if unique
            && (candidates.next().is_some()
                || diagrams
                    .iter()
                    .filter(|other| other.filename.is_empty() && key(other) == Some(value))
                    .count()
                    != 1)
        {
            continue;
        }
        diagrams[index].filename = previous.remove(candidate).filename;
    }
}

pub(crate) struct Image {
    pub path: Option<PathBuf>,
    pub hash: String,
    pub source_hash: String,
}

impl Image {
    pub(crate) fn comment(&self) -> String {
        format!("{PROVENANCE_PREFIX}{} {}", self.source_hash, self.hash)
    }

    pub(crate) fn has_published_source(&self, doc: &LocalDocument, name: &str) -> bool {
        doc.sidecar.mermaid_rendered_sources.get(name) == Some(&self.source_hash)
    }
}

pub(crate) fn source_hash_from_comment<'a>(
    comment: Option<&'a str>,
    image_hash: &str,
) -> Option<&'a str> {
    let (source_hash, png_hash) = comment?.strip_prefix(PROVENANCE_PREFIX)?.split_once(' ')?;
    (png_hash == image_hash).then_some(source_hash)
}

#[derive(Default)]
struct PageImages {
    names: Vec<Option<String>>,
    images: BTreeMap<String, Image>,
}

#[derive(Default)]
pub(crate) struct Rendered {
    pages: BTreeMap<PathBuf, PageImages>,
    directory: Option<tempfile::TempDir>,
}

impl Rendered {
    pub(crate) fn render(docs: &[LocalDocument], refresh: bool) -> Result<Self> {
        let mut rendered = Self::default();
        for doc in docs.iter().filter(|doc| enabled(doc)) {
            let diagrams = crate::markdown::publishable_mermaid_diagrams(&doc.body_markdown, doc)
                .with_context(|| doc.markdown_path.display().to_string())?;
            if diagrams.is_empty() {
                continue;
            }
            let mut page = PageImages::default();
            let mut staging = None;
            for diagram in diagrams {
                let source_hash = sha256_hex(diagram.source.as_bytes());
                let hash = if refresh {
                    None
                } else {
                    published_hash(doc, &diagram.filename, &source_hash)
                };
                let image = if let Some(hash) = hash {
                    Image {
                        path: None,
                        hash: hash.to_owned(),
                        source_hash,
                    }
                } else {
                    let (path, lines_before) = match &staging {
                        Some(staging) => staging,
                        None => {
                            let directory = match &rendered.directory {
                                Some(directory) => directory,
                                None => rendered
                                    .directory
                                    .insert(tempfile::tempdir().context("stage Mermaid images")?),
                            };
                            let path = directory.path().join(rendered.pages.len().to_string());
                            fs::create_dir(&path)?;
                            let file = fs::read_to_string(&doc.markdown_path)?;
                            let lines_before =
                                crate::sync::lines_before_body(&file, &doc.body_markdown)
                                    .unwrap_or(0);
                            staging.insert((path, lines_before))
                        }
                    };
                    let line = lines_before
                        + doc.body_markdown[..diagram.range.start]
                            .matches('\n')
                            .count()
                        + 1;
                    let image_path = path.join(&diagram.filename);
                    let hash = render(&diagram.source, &path.join("diagram.mmd"), &image_path)
                        .with_context(|| {
                            format!(
                                "{}:{line}: could not render Mermaid diagram",
                                doc.markdown_path.display()
                            )
                        })?;
                    Image {
                        path: Some(image_path),
                        hash,
                        source_hash,
                    }
                };
                page.names.push(Some(diagram.filename.clone()));
                page.images.insert(diagram.filename, image);
            }
            rendered.pages.insert(doc.directory.clone(), page);
        }
        Ok(rendered)
    }

    pub(crate) fn images(&self, doc: &LocalDocument) -> Option<&BTreeMap<String, Image>> {
        self.pages.get(&doc.directory).map(|page| &page.images)
    }

    pub(crate) fn images_changed(&self, doc: &LocalDocument) -> bool {
        self.images(doc).is_some_and(|images| {
            images.iter().any(|(name, image)| {
                image.path.is_some()
                    && (!image.has_published_source(doc, name)
                        || doc
                            .sidecar
                            .attachment_map
                            .get(name)
                            .and_then(|attachment| attachment.sha256.as_deref())
                            != Some(image.hash.as_str()))
            })
        })
    }

    pub(crate) fn sources(&self, doc: &LocalDocument) -> BTreeMap<String, String> {
        self.images(doc)
            .into_iter()
            .flatten()
            .map(|(name, image)| (name.clone(), image.source_hash.clone()))
            .collect()
    }

    pub(crate) fn names(&self, doc: &LocalDocument) -> Vec<Option<String>> {
        self.pages
            .get(&doc.directory)
            .map(|page| page.names.clone())
            .unwrap_or_default()
    }

    pub(crate) fn pending_publish(
        &self,
        doc: &LocalDocument,
        upload: Option<PendingUpload>,
    ) -> PendingPublish {
        PendingPublish {
            body: doc.body_markdown.clone(),
            names: self.names(doc),
            upload,
        }
    }
}

fn published_hash<'a>(doc: &'a LocalDocument, name: &str, source_hash: &str) -> Option<&'a str> {
    if doc
        .sidecar
        .mermaid_pending
        .as_ref()
        .and_then(|pending| pending.upload.as_ref())
        .is_some_and(|upload| upload.name == name)
    {
        return None;
    }
    if doc.sidecar.mermaid_rendered_sources.get(name)?.as_str() != source_hash {
        return None;
    }
    doc.sidecar.attachment_map.get(name)?.sha256.as_deref()
}

fn render(source: &str, input: &Path, output: &Path) -> Result<String> {
    fs::write(input, source)?;
    let result = Command::new("mmdc")
        .arg("-i")
        .arg(input)
        .arg("-o")
        .arg(output)
        .args(["-b", "white", "-s", "2", "-q"])
        .output()
        .context("run mmdc from @mermaid-js/mermaid-cli")?;
    ensure!(
        result.status.success(),
        "mmdc exited with {}: {}",
        result.status,
        String::from_utf8_lossy(&result.stderr).trim()
    );
    let bytes = fs::read(output).context("read PNG produced by mmdc")?;
    ensure!(
        bytes.starts_with(b"\x89PNG\r\n\x1a\n"),
        "mmdc did not produce a PNG"
    );
    Ok(sha256_hex(bytes))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn diagrams_added_during_retry_do_not_share_pending_attachment_names() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path();
        fs::write(
            path.join("index.md"),
            "---\ntitle: Diagrams\ntype: page\n---\n",
        )
        .unwrap();
        let mut doc = crate::markdown::load_document(path).unwrap();
        let original = "~~~mermaid\nflowchart LR\nA --> B\n~~~";
        doc.sidecar.mermaid_pending = Some(PendingPublish {
            body: original.to_string(),
            names: vec![Some("confluence-cli-mermaid-1.png".to_string())],
            upload: Some(PendingUpload {
                name: "confluence-cli-mermaid-1.png".to_string(),
                source_hash: "source".to_string(),
                image_hash: "image".to_string(),
            }),
        });
        let mut diagrams = fences(&format!(
            "~~~mermaid\nflowchart LR\nC --> D\n~~~\n\n{original}"
        ));
        name_diagrams(&doc, &mut diagrams);
        assert_eq!(diagrams[0].filename, "confluence-cli-mermaid-2.png");
        assert_eq!(diagrams[1].filename, "confluence-cli-mermaid-1.png");
    }
}
